package is.fivefivefive.CanDis.theory;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;

/** Forward-congruence proof generated by two leader records with one exact shape. */
public final class EffectiveShapeCollisionCertificate extends TypedEqualityCertificate {
    /** Expected failure: one directed occurrence map does not embed the interface. */
    static final class IncompatibleInterfaces extends IllegalArgumentException {
        private IncompatibleInterfaces(String message) {
            super(message);
        }
    }

    private final CanonicalShape shape;
    private final TypedEClassInterface child;
    private final TypedInvocation parentInvocation;
    private final TypedEqualityCertificate endpointDerivation;

    private EffectiveShapeCollisionCertificate(Build build) {
        super(
                CertificateCategory.FORWARD_CONGRUENCE,
                build.left,
                build.right,
                Collections.singletonList(build.derivation),
                Arrays.asList(
                        build.shape.structuralKey(),
                        TheoryKeys.eclass(build.child),
                        TheoryKeys.invocation(build.parentInvocation)));
        this.shape = build.shape;
        this.child = build.child;
        this.parentInvocation = build.parentInvocation;
        this.endpointDerivation = build.derivation;
        verifyLocal();
    }

    static EffectiveShapeCollisionCertificate create(
            CanonicalShape shape,
            TypedEClassRecord childRecord,
            ShapeWitness childWitness,
            TypedEqualityCertificate childEquation,
            TypedEClassRecord parentRecord,
            ShapeWitness parentWitness,
            TypedEqualityCertificate parentEquation) {
        return new EffectiveShapeCollisionCertificate(build(
                shape,
                childRecord,
                childWitness,
                childEquation,
                parentRecord,
                parentWitness,
                parentEquation));
    }

    private static Build build(
            CanonicalShape shape,
            TypedEClassRecord childRecord,
            ShapeWitness childWitness,
            TypedEqualityCertificate childEquation,
            TypedEClassRecord parentRecord,
            ShapeWitness parentWitness,
            TypedEqualityCertificate parentEquation) {
        Objects.requireNonNull(shape, "shape");
        Objects.requireNonNull(childRecord, "childRecord");
        Objects.requireNonNull(parentRecord, "parentRecord");
        if (childRecord.id().equals(parentRecord.id())) {
            throw new IllegalArgumentException("A shape collision requires distinct leaders");
        }
        TypedEqualityCertificate childEq = orientShapeEquation(
                shape, childRecord, childWitness, childEquation);
        TypedEqualityCertificate parentEq = orientShapeEquation(
                shape, parentRecord, parentWitness, parentEquation);

        TypedRenaming parentToChildAmbient = parentWitness.instantiatingRenaming()
                .inverse()
                .andThen(childWitness.instantiatingRenaming());
        TypedEmbedding parentInChildAmbient = TypedEmbedding.inclusion(
                parentRecord.exposedSlots(), parentWitness.ambientSupport())
                .andThen(parentToChildAmbient);
        Map<TypedSlot, TypedSlot> inducedMap = new LinkedHashMap<>();
        for (TypedSlot slot : parentRecord.exposedSlots()) {
            TypedSlot target = parentInChildAmbient.apply(slot);
            if (!childRecord.exposedSlots().contains(target)) {
                throw new IncompatibleInterfaces(
                        "Colliding witnesses do not induce the requested parent embedding");
            }
            if (inducedMap.containsValue(target)) {
                throw new IncompatibleInterfaces(
                        "Colliding witnesses induce a noninjective parent embedding");
            }
            inducedMap.put(slot, target);
        }
        TypedEmbedding induced = TypedEmbedding.of(
                parentRecord.exposedSlots(), childRecord.exposedSlots(), inducedMap);
        TypedInvocation parentInvocation = new TypedInvocation(
                parentRecord.interfaceView(), induced);

        TypedEqualityCertificate parentInChild = EqualityCertificates.rename(
                parentEq, parentToChildAmbient);
        TypedEqualityCertificate ambient = EqualityCertificates.transitive(
                EqualityCertificates.symmetric(childEq), parentInChild);
        TypedEmbedding childInAmbient = TypedEmbedding.inclusion(
                childRecord.exposedSlots(), childWitness.ambientSupport());
        TypedEqualityCertificate restricted = EqualityCertificates.restrict(
                ambient,
                TypedCertificateEndpoint.eclassWitness(childRecord.interfaceView()),
                TypedCertificateEndpoint.invocation(parentInvocation),
                childInAmbient);
        CertificateVerifier.verify(restricted);
        return new Build(
                shape,
                childRecord.interfaceView(),
                parentInvocation,
                restricted);
    }

    static TypedEqualityCertificate orientShapeEquation(
            CanonicalShape shape,
            TypedEClassRecord owner,
            ShapeWitness witness,
            TypedEqualityCertificate equation) {
        Objects.requireNonNull(witness, "witness");
        TypedCertificateEndpoint node = TypedCertificateEndpoint.node(
                shape.node().act(witness.instantiatingRenaming()));
        TypedEmbedding ownerInAmbient = TypedEmbedding.inclusion(
                owner.exposedSlots(), witness.ambientSupport());
        TypedCertificateEndpoint eclass = TypedCertificateEndpoint.invocation(
                new TypedInvocation(owner.interfaceView(), ownerInAmbient));
        CertificateVerifier.verify(Objects.requireNonNull(equation, "equation"));
        return EqualityCertificates.orient(equation, node, eclass);
    }

    public CanonicalShape shape() {
        return shape;
    }

    public TypedEClassInterface child() {
        return child;
    }

    public TypedInvocation parentInvocation() {
        return parentInvocation;
    }

    public TypedEqualityCertificate endpointDerivation() {
        return endpointDerivation;
    }

    @Override
    void verifyLocal() {
        if (!leftEndpoint().equals(TypedCertificateEndpoint.eclassWitness(child))
                || !rightEndpoint().equals(
                        TypedCertificateEndpoint.invocation(parentInvocation))
                || child.id().equals(parentInvocation.eclass().id())) {
            throw new IllegalStateException("Malformed effective-shape collision certificate");
        }
    }

    private static final class Build {
        private final CanonicalShape shape;
        private final TypedEClassInterface child;
        private final TypedInvocation parentInvocation;
        private final TypedCertificateEndpoint left;
        private final TypedCertificateEndpoint right;
        private final TypedEqualityCertificate derivation;

        private Build(
                CanonicalShape shape,
                TypedEClassInterface child,
                TypedInvocation parentInvocation,
                TypedEqualityCertificate derivation) {
            this.shape = shape;
            this.child = child;
            this.parentInvocation = parentInvocation;
            this.left = TypedCertificateEndpoint.eclassWitness(child);
            this.right = TypedCertificateEndpoint.invocation(parentInvocation);
            this.derivation = derivation;
        }
    }
}
